    15	public class MessageService {
    16	    private static final String ARCHIVE_EMAIL = "arquivo@pousadamarealta.com.br";
    17	    private static final String TEST_EMAIL = "testes@pousadamarealta.com.br";
    18	    private static final boolean TEST_MODE = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
    19	
    20	    public static void sendMessage(String to, String subject, String body) throws SQLException {
    21	        Message message = new Message();
    22	        message.channel = "EMAIL";
    23	        message.subject = subject;
    24	        message.body = body;
    25	
    26	        if (!EmailValidator.isValid(to)) {
    27	            message.to = to;
    28	            message.status = "BLOCKED";
    29	            saveMessage(message);
    30	            return;
    31	        }
    32	
    33	        String finalTo = to;
    34	        String finalSubject = subject;
    35	        String finalBody = body;
    36	
    37	        if (TEST_MODE) {
    38	            finalSubject = "[TESTE] " + subject;
    39	            finalBody = "Destinatário original: " + to + "\n\n" + body;
    40	            finalTo = TEST_EMAIL;
    41	        }
    42	
    43	        message.to = finalTo;
    44	        message.status = "SENT";
    45	        saveMessage(message);
    46	
    47	        if (!TEST_MODE && EmailValidator.isValid(to)) {
    48	            Message archive = new Message();
    49	            archive.channel = "EMAIL";
    50	            archive.to = ARCHIVE_EMAIL;
    51	            archive.subject = "[Cópia] " + subject;
    52	            archive.body = body;
    53	            archive.status = "SENT";
    54	            saveMessage(archive);
    55	        }
    56	    }
    57	
    58	    private static void saveMessage(Message message) throws SQLException {
    59	        try (Connection conn = Database.getConnection();
    60	             PreparedStatement stmt = conn.prepareStatement(
    61	                     "INSERT INTO messages (channel, \"to\", subject, body, status) VALUES (?, ?, ?, ?, ?)",
    62	                     Statement.RETURN_GENERATED_KEYS)) {
    63	
    64	            stmt.setString(1, message.channel);
    65	            stmt.setString(2, message.to);
    66	            stmt.setString(3, message.subject);
    67	            stmt.setString(4, message.body);
    68	            stmt.setString(5, message.status);
    69	
    70	            stmt.executeUpdate();
    71	
    72	            var keys = stmt.getGeneratedKeys();
    73	            if (keys.next()) {
    74	                message.id = keys.getInt(1);
    75	            }
    76	        }
    77	    }
    78	
    79	    public static List<Message> getMessages() throws SQLException {
    80	        List<Message> messages = new ArrayList<>();
    81	
    82	        try (Connection conn = Database.getConnection();
    83	             var stmt = conn.createStatement()) {
    84	
    85	            var result = stmt.executeQuery("SELECT id, channel, \"to\", subject, body, status FROM messages ORDER BY id");
    86	
    87	            while (result.next()) {
    88	                messages.add(new Message(
    89	                        result.getInt("id"),
    90	                        result.getString("channel"),
    91	                        result.getString("to"),
    92	                        result.getString("subject"),
    93	                        result.getString("body"),
    94	                        result.getString("status")
    95	                ));
    96	            }
    97	        }
    98	
    99	        return messages;
   100	    }
   101	}
